import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadVrData(){const e=readFileSync(resolve(__dirname,"../../frontend/vir-chakra-explorer/vr-data.js"),"utf-8");return new Function(e+"\nreturn { VR_INFO, VR_HISTORY, VR_ELIGIBILITY, VR_MEDAL_DESIGN, VR_HEROISM_TYPES, VR_AWARDEES, VR_TIMELINE, VR_FACTS };")()}describe("Vir Chakra Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadVrData()}),describe("VR_INFO metadata",()=>{it("contains correct award metadata and statistics",()=>{expect(e.VR_INFO.id).toBe("vir-chakra"),expect(e.VR_INFO.totalRecipients).toBe(1322),expect(e.VR_INFO.ribbonColor).toContain("dark blue"),expect(Array.isArray(e.VR_INFO.quickStats)).toBe(!0),expect(e.VR_INFO.quickStats.length).toBe(6)})}),describe("VR_HISTORY & MEDAL_DESIGN",()=>{it("contains history, wartime significance, and silver star medal design specs",()=>{expect(e.VR_HISTORY.overview).toBeDefined(),expect(e.VR_HISTORY.wartimeSignificance).toBeDefined(),expect(e.VR_MEDAL_DESIGN.obverse).toContain("Five-pointed"),expect(e.VR_MEDAL_DESIGN.ribbon).toContain("half dark blue")})}),describe("VR_AWARDEES catalog",()=>{it("contains heroes like Abhinandan Varthaman, AB Devayya, and Balwan Singh",()=>{expect(Array.isArray(e.VR_AWARDEES)).toBe(!0),expect(e.VR_AWARDEES.length).toBeGreaterThanOrEqual(5);const t=e.VR_AWARDEES.find(e=>"abhinandan-varthaman"===e.id),a=e.VR_AWARDEES.find(e=>"ajjamada-devayya"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(t.citation).toContain("F-16"),expect(a.citation).toContain("Starfighter")})}),describe("VR_TIMELINE & FACTS",()=>{it("has timeline milestones and interesting facts",()=>{expect(Array.isArray(e.VR_TIMELINE)).toBe(!0),expect(e.VR_TIMELINE.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.VR_FACTS)).toBe(!0),expect(e.VR_FACTS.length).toBe(6)})}),describe("Landing Page Integration",()=>{it("is integrated into awards-of-india-explorer landing page",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("../vir-chakra-explorer/index.html"),expect(e).toContain("Vir Chakra")})})});